const prom = new Promise<string>((resolve, reject) => {
	return setTimeout(() => {
		let success = true
		if (success) {
			return resolve("Hello, world!")
		}
		else {
			return reject(new Error("Failed to generate greeting"))
		}
	}
    , 1000)
}
    )

truthy(isPromise(prom))
falsy( isPromise(42))
falsy( isPromise(undef))
falsy( isPromise(null))

